import { IconExpandLess, IconExpandMore, IconClose } from "@airbus/icons";
import { pxToRem, svgColor, svgUri } from "../../helpers";
import { List } from "../List";
import { StyleFn } from "..";

export const SideNav: StyleFn = (theme, mode) => {
  const { color, font, size, elevation, responsive } = theme;
  const { root: list, item: listItem, item_disabled } = List(theme, mode);
  const itemsTextColor = color.text.accent.corporate[mode];

  const prepQuery = (value: string) => `@media (max-width:${value}px)`;

  // recursive category level styles
  const getCategoryLevels = (levels: number) => {
    let currentLevel = 1;
    const getLevel = (): any => ({
      "& $category": {
        "& $itemLink": {
          paddingLeft: pxToRem(16 + currentLevel * 8),
        },
        // since max allowed levels is 3, we support until that and no indendation afterwards
        "& $section $itemLink": {
          ...(currentLevel > 2 ? {
            paddingLeft: pxToRem(24 + currentLevel * 8 + 2),

          } : {
            paddingLeft: size.spacing[12],
            marginLeft: `calc(${size.spacing[32]} + 2px)`
          }),
          "&:after": {
            left: size.spacing[32],
          },
        },
        "& $item $itemLink": {
          "&:after": {
            content: '""',
            position: "absolute",
            top: 0,
            left: size.spacing[16],
            bottom: 0,
            borderLeft: `solid 2px ${color.surface.componentbackground.moderate[mode]}`,
          },
        },
        ...(currentLevel++ < levels && getLevel()),
      },
    });
    return getLevel();
  };
  return {
    root: {
      height: "100%",
      overflowY: "auto",
      width: pxToRem(224),
      display: "flex",
      flexDirection: "column",
      backgroundColor: color.surface.elevation[2][mode],
      color: color.text.accent.corporate[mode],
      boxShadow: elevation.level1,
      "& > $section": {
        paddingTop: size.spacing[8],
      },
      ...Object.keys(responsive.breakpoint).reduce(
        (acc, bp) => ({
          ...acc,
          [prepQuery((responsive.breakpoint as any)[bp])]: {
            [`&$width-${bp}`]: {
              width: "100vw",
              zIndex: elevation.zindex.drawer,
            },
            "& $titleSection": {
              display: "flex",
            },
          },
        }),
        {}
      ),
    },
    section: {
      ...list,
      color: itemsTextColor,
      padding: 0,
    },
    item: {
      position: "relative",
      fontWeight: font.weight.regular,
    },
    itemLink: {
      ...listItem,
      justifyContent: "space-between",
      padding: `${size.spacing[12]}`,
      textDecoration: "none",
      color: itemsTextColor,
      "& svg, & i": {
        height: font.size.medium,
        lineHeight: font.size.medium,
        fontSize: font.size.medium,
        alignSelf: "center",
        fill: "currentColor",
      },
    },
    _large: {
      "& $itemLink": {
        fontSize: font.size.large,
        "& svg, & i": {
          height: font.size["heading-5"],
          fontSize: font.size["heading-5"],
        },
      },
    },
    item_disabled,
    item_selected: {
      fontWeight: font.weight.bold,
      "& > $itemLink, & > $itemLink:hover": {
        backgroundColor: color.surface.interaction.active[mode],
        color: color.text.accent.corporate[mode]
      },
    },
    category: {
      extend: "item",
      "& > $itemLink": {
        // FIXME would be better managed with an ":after" pseudo class
        // that would fix the react storybook accessibility check about color contrast
        backgroundImage: svgUri(svgColor(IconExpandMore.data, itemsTextColor)),
        backgroundPosition: "right 1rem center",
        backgroundRepeat: "no-repeat",
        backgroundSize: size.spacing[20],
        [`@media (max-width:${responsive.breakpoint.xs}px)`]: {
          backgroundPosition: "right 1rem center",
          backgroundSize: size.spacing[20],
        },
      },
      "& $section $itemLink": {
        paddingLeft: `calc(${size.spacing[24]} + 2px)`,
      },
      ...getCategoryLevels(4),
    },
    category_closed: {
      "& > $section": {
        display: "none",
        height: 0,
      },
      "&$category_selected > $itemLink": {
        backgroundImage: svgUri(
          svgColor(IconExpandMore.data, color.text.accent.corporate[mode])
        ),
      },
    },
    category_opened: {
      "& > $itemLink": {
        fontWeight: font.weight.bold,
        backgroundImage: svgUri(svgColor(IconExpandLess.data, color.text.accent.corporate[mode])),
      },
      "&$category_selected > $itemLink": {
        backgroundImage: svgUri(
          svgColor(IconExpandLess.data, color.text.accent.corporate[mode])
        ),
      },
    },
    category_current: {
      "& $item_selected > $itemLink:after": {
        borderLeft: `solid 2px ${color.surface.accent.active[mode]} !important`,
      },
    },
    category_selected: {
      "& > $itemLink, & > $itemLink:hover": {
        color: color.text.accent.corporate[mode],
      },
    },
    titleSection: {
      display: "none",
      justifyContent: "space-between",
      alignItems: "end",
      listStyleType: "none",
      padding: "1rem",
      margin: "0",
    },
    title: {
      fontSize: font.size["heading-4"],
      whiteSpace: "nowrap",
      textOverflow: "ellipsis",
      overflow: "hidden",
      margin: "auto 0px",
      color: color.text.accent.corporate[mode]
    },
    close: {
      cursor: "pointer",
      height: size.spacing["48"],
      width: size.spacing["48"],
      backgroundImage: svgUri(svgColor(IconClose.data, itemsTextColor)),
      backgroundRepeat: "no-repeat",
      alignSelf: "center",
    },
    headerPadding: {
      paddingTop: size.spacing[56],
    },
    "width-xxs": {},
    "width-xs": {},
    "width-sm": {},
    "width-md": {},
    "width-lg": {},
    "width-xl": {},
    "width-xxl": {},
  };
};
